-- KO-348: complete visual coverage for the current Chapter 01–03 curriculum.
BEGIN;
WITH blocks(slug, block_type, data_status, content) AS (VALUES
('inflation-101','worked_example','calculated',$json${"en":{"icon":"🛒","eyebrow":"Purchasing-power chart","title":"The same Rp100k can buy fewer items","altText":"A before-and-after calculation compares five Rp20,000 items with four Rp25,000 items within the same budget.","disclosure":"Calculated illustration only; prices and inflation vary by item, place, and time.","payload":{"inputs":[{"label":"Before","value":"5 × Rp20k = Rp100k"},{"label":"After","value":"4 × Rp25k = Rp100k"}],"steps":["The price per item rises by Rp5k.","The unchanged Rp100k budget now reaches four items, not five."],"outcome":"Inflation can reduce purchasing power."}} ,"id":{"icon":"🛒","eyebrow":"Grafik daya beli","title":"Rp100 ribu yang sama dapat membeli lebih sedikit barang","altText":"Perhitungan sebelum dan sesudah membandingkan lima barang Rp20.000 dengan empat barang Rp25.000 dalam anggaran yang sama.","disclosure":"Ilustrasi perhitungan saja; harga dan inflasi berbeda menurut barang, tempat, dan waktu.","payload":{"inputs":[{"label":"Sebelum","value":"5 × Rp20 ribu = Rp100 ribu"},{"label":"Sesudah","value":"4 × Rp25 ribu = Rp100 ribu"}],"steps":["Harga tiap barang naik Rp5 ribu.","Anggaran Rp100 ribu yang sama kini menjangkau empat barang, bukan lima."],"outcome":"Inflasi dapat mengurangi daya beli."}}}$json$::jsonb),
('net-worth-know-your-financial-position','worked_example','illustrative',$json${"en":{"icon":"⚖️","eyebrow":"Net-worth snapshot","title":"What you own minus what you owe","altText":"A worked example subtracts Rp8m of liabilities from Rp20m of assets to show a Rp12m net position.","disclosure":"Illustrative snapshot only; a net-worth number is not a measure of personal worth.","payload":{"inputs":[{"label":"Assets","value":"Rp20m"},{"label":"Liabilities","value":"Rp8m"}],"steps":["List what you own.","Subtract obligations you need to repay."],"outcome":"Illustrative net position: Rp12m."}} ,"id":{"icon":"⚖️","eyebrow":"Potret kekayaan bersih","title":"Yang dimiliki dikurangi yang terutang","altText":"Contoh perhitungan mengurangi liabilitas Rp8 juta dari aset Rp20 juta untuk menunjukkan posisi bersih Rp12 juta.","disclosure":"Potret ilustratif saja; angka kekayaan bersih bukan ukuran nilai diri.","payload":{"inputs":[{"label":"Aset","value":"Rp20 juta"},{"label":"Liabilitas","value":"Rp8 juta"}],"steps":["Daftarkan yang dimiliki.","Kurangi kewajiban yang perlu dibayar kembali."],"outcome":"Posisi bersih ilustratif: Rp12 juta."}}}$json$::jsonb),
('budgeting-101','comparison','illustrative',$json${"en":{"icon":"🍱","eyebrow":"Budget map","title":"Give each rupiah a job before it disappears","altText":"A three-column budget map groups needs, wants, and goals using a flexible 50/30/20 starting framework.","disclosure":"Illustrative starting framework only; adapt it to your income, dependants, debt, and local costs.","payload":{"leftTitle":"Needs 🧾","rightTitle":"Wants & goals 🎯","rows":[{"left":"Essentials first","right":"Flexible spending after essentials"},{"left":"Rent, food, transport","right":"Fun, saving, debt goals"},{"left":"Review actual costs","right":"Adjust deliberately"}]}},"id":{"icon":"🍱","eyebrow":"Peta anggaran","title":"Beri setiap rupiah tugas sebelum habis","altText":"Peta anggaran tiga kolom mengelompokkan kebutuhan, keinginan, dan tujuan dengan kerangka awal 50/30/20 yang fleksibel.","disclosure":"Kerangka awal ilustratif saja; sesuaikan dengan pendapatan, tanggungan, utang, dan biaya lokal.","payload":{"leftTitle":"Kebutuhan 🧾","rightTitle":"Keinginan & tujuan 🎯","rows":[{"left":"Kebutuhan pokok lebih dulu","right":"Belanja fleksibel setelah kebutuhan"},{"left":"Sewa, makanan, transportasi","right":"Hiburan, tabungan, tujuan utang"},{"left":"Tinjau biaya nyata","right":"Sesuaikan dengan sadar"}]}}}$json$::jsonb),
('banking-basics-choosing-the-right-account','comparison','illustrative',$json${"en":{"icon":"🏦","eyebrow":"Account fit","title":"Match the account to the job you need it to do","altText":"A comparison asks about access, fees, minimum balance, and purpose before choosing an account.","disclosure":"Illustrative checklist only; verify current terms directly with the provider.","payload":{"leftTitle":"Daily access 💳","rightTitle":"Goal account 🎯","rows":[{"left":"How often will you use it?","right":"What goal will it hold money for?"},{"left":"Check fees and access","right":"Check balance rules and transfer access"},{"left":"Keep security enabled","right":"Keep the purpose visible"}]}},"id":{"icon":"🏦","eyebrow":"Kecocokan rekening","title":"Cocokkan rekening dengan tugas yang Anda perlukan","altText":"Perbandingan menanyakan akses, biaya, saldo minimum, dan tujuan sebelum memilih rekening.","disclosure":"Daftar periksa ilustratif saja; verifikasi syarat terbaru langsung kepada penyedia.","payload":{"leftTitle":"Akses harian 💳","rightTitle":"Rekening tujuan 🎯","rows":[{"left":"Seberapa sering akan digunakan?","right":"Tujuan apa yang akan ditampung?"},{"left":"Cek biaya dan akses","right":"Cek aturan saldo dan akses transfer"},{"left":"Aktifkan keamanan","right":"Jaga tujuan tetap terlihat"}]}}}$json$::jsonb),
('digital-wallets-qris-safe-and-smart-usage','process','illustrative',$json${"en":{"icon":"📱","eyebrow":"QRIS check","title":"Check the merchant and amount before you pay","altText":"A three-step QRIS payment flow checks merchant, amount, and confirmation without sharing a PIN or OTP.","disclosure":"Never share a PIN, password, or OTP; use official app support for a real issue.","payload":{"steps":[{"title":"1. Check the merchant","description":"Confirm the displayed name matches where you are paying."},{"title":"2. Check the amount","description":"Read the total before confirming."},{"title":"3. Keep proof","description":"Save the confirmation and report a mismatch through official support."}]}},"id":{"icon":"📱","eyebrow":"Cek QRIS","title":"Periksa merchant dan jumlah sebelum membayar","altText":"Alur pembayaran QRIS tiga langkah memeriksa merchant, jumlah, dan konfirmasi tanpa membagikan PIN atau OTP.","disclosure":"Jangan pernah membagikan PIN, kata sandi, atau OTP; gunakan dukungan aplikasi resmi untuk masalah nyata.","payload":{"steps":[{"title":"1. Cek merchant","description":"Pastikan nama yang tampil cocok dengan tempat pembayaran."},{"title":"2. Cek jumlah","description":"Baca total sebelum mengonfirmasi."},{"title":"3. Simpan bukti","description":"Simpan konfirmasi dan laporkan ketidaksesuaian lewat dukungan resmi."}]}}}$json$::jsonb),
('insurance-basics-bpjs-vs-private-insurance','comparison','illustrative',$json${"en":{"icon":"🛡️","eyebrow":"Protection comparison","title":"Compare coverage, cost, and fit—not just a label","altText":"A comparison encourages checking what is covered, who is eligible, and what costs or limits apply.","disclosure":"Illustrative learning comparison only; verify current eligibility, coverage, and terms with official providers.","payload":{"leftTitle":"BPJS 🏥","rightTitle":"Private insurance 🛡️","rows":[{"left":"Check official eligibility and coverage","right":"Check product coverage and exclusions"},{"left":"Understand referral and service rules","right":"Understand network, limits, and claims rules"},{"left":"Use official information","right":"Compare terms before choosing"}]}},"id":{"icon":"🛡️","eyebrow":"Perbandingan perlindungan","title":"Bandingkan cakupan, biaya, dan kecocokan—bukan hanya label","altText":"Perbandingan mendorong pemeriksaan apa yang ditanggung, siapa yang memenuhi syarat, serta biaya atau batas yang berlaku.","disclosure":"Perbandingan pembelajaran ilustratif saja; verifikasi kelayakan, cakupan, dan syarat terbaru kepada penyedia resmi.","payload":{"leftTitle":"BPJS 🏥","rightTitle":"Asuransi swasta 🛡️","rows":[{"left":"Cek kelayakan dan cakupan resmi","right":"Cek cakupan produk dan pengecualian"},{"left":"Pahami aturan rujukan dan layanan","right":"Pahami jaringan, batas, dan klaim"},{"left":"Gunakan informasi resmi","right":"Bandingkan syarat sebelum memilih"}]}}}$json$::jsonb)
)
INSERT INTO public.lesson_visual_blocks (lesson_id, placement, block_type, content, data_status, display_order, is_published)
SELECT lesson.id, 'concept', blocks.block_type, blocks.content, blocks.data_status, 10, TRUE FROM blocks JOIN public.lessons lesson ON lesson.slug=blocks.slug WHERE lesson.is_published
ON CONFLICT (lesson_id, placement, display_order) DO UPDATE SET block_type=EXCLUDED.block_type, content=EXCLUDED.content, data_status=EXCLUDED.data_status, is_published=TRUE;
COMMIT;
